const CATALOG = [
  { id: 'mug', name: 'Enamel mug', price: 12.5 },
  { id: 'socks', name: 'Wool socks', price: 18 },
  { id: 'beans', name: 'Coffee beans', price: 9.75 },
];

// Quantity per item id. Zero means the line is gone from the cart.
const quantities = { mug: 1, socks: 2, beans: 0 };

const list = document.getElementById('items');
const countOut = document.getElementById('count');
const subtotalOut = document.getElementById('subtotal');

function money(n) {
  return `$${n.toFixed(2)}`;
}

function change(id, delta) {
  quantities[id] = Math.max(0, (quantities[id] || 0) + delta);
  render();
  updateSummary();
}

function render() {
  list.textContent = '';
  for (const item of CATALOG) {
    const quantity = quantities[item.id] || 0;
    if (quantity === 0) continue;

    const row = document.createElement('li');

    const name = document.createElement('span');
    name.className = 'name';
    name.textContent = item.name;

    const minus = document.createElement('button');
    minus.textContent = '-';
    minus.addEventListener('click', () => change(item.id, -1));

    const amount = document.createElement('span');
    amount.textContent = String(quantity);

    const plus = document.createElement('button');
    plus.textContent = '+';
    plus.addEventListener('click', () => change(item.id, 1));

    const lineTotal = document.createElement('span');
    lineTotal.textContent = money(item.price * quantity);

    row.append(name, minus, amount, plus, lineTotal);
    list.append(row);
  }
}

function updateSummary() {
  let count = 0;
  let subtotal = 0;
  for (const item of CATALOG) {
    const quantity = quantities[item.id] || 0;
    count += quantity;
    subtotal += quantity * item.price;
  }
  countOut.textContent = String(count);
  subtotalOut.textContent = money(subtotal);
  document.body.classList.toggle('is-empty', count === 0);
}

render();
updateSummary();
